                    sub=parse_html(decode_bytes(data,opts,ct))
                    transform(sub,u,fetcher,opts,target_url=u,is_http_target=urllib.parse.urlparse(u).scheme in ('http','https'))
                    n.set('src', data_url(serialize_doc(sub).encode('utf-8'),'text/html'))
        elif tag=='body':
            embed_attr(n,'background',base,fetcher,opts,'image')
        elif tag=='form' and n.get('action'):
            n.set('action', abs_url(n.get('action'), base))
        elif tag in ('a','area') and n.get('href'):
            n.set('href', abs_url(n.get('href'), base))
        for c in list(n.children): walk(c,n)
    walk(doc['html'])

    # unwrap noscript by changing serializer-relevant marker nodes
    if opts.unwrap_noscript:
