        for c in root.children:
            if c.kind=='element' and c.tag=='head': head=c
            elif c.kind=='element' and c.tag=='body': body=c
            else: body.children.append(c)
        html_node.children=[head, body]
    else:
        head=find_child(html_node,'head')
        body=find_child(html_node,'body')
        if head is None:
            head=Node('element','head')
            html_node.children.insert(0, head)
        if body is None:
            body=Node('element','body')
