def file_url(path):
    return urllib.parse.urlunparse(('file','',urllib.request.pathname2url(os.path.abspath(path)),'','',''))

def classify_target(t):
    if t=='-': return 'stdin', None
    pr=urllib.parse.urlparse(t)
    if pr.scheme in ('http','https','file'): return pr.scheme, t
    if os.path.isfile(t): return 'file', file_url(t)
    # URL-like fallback, matching url crate-ish behavior sufficiently.
    u='http://'+t
    pr=urllib.parse.urlparse(u)
    if not pr.path and not u.endswith('/'):
