    return 'http', u

def domain_match(host, domain):
    if not host: return False
    host=host.lower().rstrip('.')
    d=domain.lower().rstrip('.')
    if d.startswith('.'):
        return host.endswith(d) or host==d[1:]
    return host==d

def allowed_url(url, opts):
    if not opts.domains: return True
    pr=urllib.parse.urlparse(url)
    if pr.scheme=='file': return True
    matched=any(domain_match(pr.hostname or '', d) for d in opts.domains)
    return (not matched) if opts.blacklist else matched

class Fetcher:
    def __init__(self, opts):
