            if os.path.isfile(path):
                self.log(url)
                data=open(path,'rb').read(); ct=guess_type(path, None, False); err=None
            else:
                err='file not found'; self.log(url+' ('+err+')'); data=None; ct=None
        elif pr.scheme in ('http','https'):
            req=urllib.request.Request(url, headers={'User-Agent':self.opts.user_agent})
            ctx=None
            if pr.scheme=='https' and self.opts.insecure: ctx=ssl._create_unverified_context()
            try:
                resp=self.opener.open(req, timeout=self.opts.timeout, context=ctx) if ctx else self.opener.open(req, timeout=self.opts.timeout)
                data=resp.read(); ct=resp.headers.get_content_type() if hasattr(resp.headers,'get_content_type') else resp.headers.get('Content-Type','').split(';')[0]
                final=resp.geturl(); self.log(url if final==url else final); err=None
            except urllib.error.HTTPError as e:
                err=str(e.code)+' '+(e.reason or ''); self.log(url+' ('+err+')'); data=None; ct=None
            except Exception as e:
                err='error sending request for url ('+url+')'; self.log(url+' ('+err+')'); data=None; ct=None
        else:
            err='unsupported URL scheme'; self.log(url+' ('+err+')'); data=None; ct=None
        self.cache[url]=(data,ct,err)
        return data,ct,err

def guess_type(name, header_ct=None, is_http=False):
    if header_ct and header_ct!='application/octet-stream': return header_ct.split(';')[0]
    ext=os.path.splitext(urllib.parse.urlparse(name).path)[1].lower()
    table={'.css':'text/css','.html':'text/html','.htm':'text/html','.png':'image/png','.jpg':'image/jpeg','.jpeg':'image/jpeg',
           '.gif':'image/gif','.svg':'image/svg+xml','.webp':'image/webp','.ico':'image/vnd.microsoft.icon' if is_http else 'image/x-icon',
           '.mp3':'audio/mpeg','.ogg':'audio/ogg','.wav':'audio/wav','.mp4':'video/mp4','.woff':'font/woff','.woff2':'font/woff2',
           '.ttf':'font/ttf','.otf':'font/otf','.txt':'text/plain'}
    if ext in table: return table[ext]
    mt=mimetypes.guess_type(name)[0]
    return mt or ''

def data_url(data, mime):
    return 'data:'+ (mime or '') + ';base64,' + base64.b64encode(data or b'').decode('ascii')

def abs_url(url, base):
    if not url or url.startswith(('data:','mailto:','javascript:','tel:','#')): return url
    return urllib.parse.urljoin(base or '', url)

def css_rewrite(css, base, fetcher, opts):
    if opts.no_fonts:
        css=re.sub(r'@font-face\s*\{[^{}]*(?:\{[^{}]*\}[^{}]*)*\}\s*','',css,flags=re.I|re.S)
    def repl(m):
        raw=m.group(2).strip()
        if not raw or raw.startswith(('data:','#')): return m.group(0)
        u=abs_url(raw, base)
        ext=os.path.splitext(urllib.parse.urlparse(u).path)[1].lower()
        if opts.no_images and ext in ('.png','.jpg','.jpeg','.gif','.svg','.webp','.bmp','.ico'):
            return 'url("'+PLACEHOLDER_IMAGE+'")'
        data,ct,err=fetcher.fetch(u)
        if err or data is None: return 'url("'+u+'")'
        mime=guess_type(u, ct, urllib.parse.urlparse(u).scheme in ('http','https'))
        if opts.no_fonts and (mime.startswith('font/') or ext in ('.woff','.woff2','.ttf','.otf','.eot')):
            return 'url("")'
        return 'url("'+data_url(data,mime)+'")'
    return re.sub(r'url\(\s*([\"\']?)(.*?)(?:\1)\s*\)', repl, css, flags=re.I|re.S)

def decode_bytes(b, opts, ct=None):
    enc=opts.encoding
    if not enc and ct:
        m=re.search(r'charset=([^;]+)', ct, re.I)
        if m: enc=m.group(1).strip().strip('"')
    if not enc: enc='utf-8'
    try: return b.decode(enc, errors='replace')
    except Exception: return b.decode('utf-8', errors='replace')

def attr_parent_kind(parent):
    return parent.tag if parent and parent.kind=='element' else ''

def rewrite_srcset(v, base, fetcher, opts, kind='image'):
    parts=[]
    for item in v.split(','):
        s=item.strip()
        if not s: continue
        bits=s.split()
        url=bits[0]; desc=' '.join(bits[1:])
        if opts.no_images and kind=='image': new=PLACEHOLDER_IMAGE
        else:
            u=abs_url(url, base); data,ct,err=fetcher.fetch(u)
            new=data_url(data, guess_type(u,ct,urllib.parse.urlparse(u).scheme in ('http','https'))) if not err and data is not None else u
        parts.append(new + ((' '+desc) if desc else ''))
    return ', '.join(parts)

def embed_attr(node, attr, base, fetcher, opts, kind):
    val=node.get(attr)
    if val is None: return
    if kind=='image' and opts.no_images:
        node.set(attr, PLACEHOLDER_IMAGE); return
    if kind=='audio' and opts.no_audio:
        node.remove(attr); return
    if kind=='video' and opts.no_video:
        node.remove(attr); return
    u=abs_url(val, base); data,ct,err=fetcher.fetch(u)
    if err or data is None:
        node.remove(attr) if attr in ('src','href') else node.set(attr,u)
    else:
        node.set(attr, data_url(data, guess_type(u,ct,urllib.parse.urlparse(u).scheme in ('http','https'))))

def first_base(doc, fallback):
    for n,p in iter_nodes(doc['html']):
        if n.kind=='element' and n.tag=='base' and n.get('href'):
            return n.get('href')
    return fallback

def transform(doc, base, fetcher, opts, target_url=None, is_http_target=False):
    head=find_child(doc['html'],'head'); body=find_child(doc['html'],'body')
    if head is None:
        head=Node('element','head'); doc['html'].children.insert(0,head)
    if body is None:
        body=Node('element','body'); doc['html'].children.append(body)
    # custom base element requested
    if opts.base_url:
        # Use a closing base tag, as the reference does for inserted base elements.
        head.children.append(Node('element','base',attrs=[('href',opts.base_url)],force_close=True))
        base=opts.base_url
    base=first_base(doc, base)

    # recursive element transforms
    def walk(n,parent=None):
        nonlocal base
        if n.kind!='element': return
        tag=n.tag
        # remove inline event handlers when JavaScript is disabled
        if opts.no_js:
            n.attrs=[(k,v) for k,v in n.attrs if not k.startswith('on')]
        # inline style
        if n.get('style') is not None:
            if opts.no_css: n.remove('style')
            else: n.set('style', css_rewrite(n.get('style'), base, fetcher, opts))
        if tag=='base' and n.get('href'):
            base=n.get('href')
        elif tag=='link':
            rel=(n.get('rel') or '').lower()
            if 'stylesheet' in rel:
                if opts.no_css: n.remove('href')
                elif n.get('href'):
                    u=abs_url(n.get('href'), base); data,ct,err=fetcher.fetch(u)
                    if err or data is None: n.remove('href')
                    else:
                        css=decode_bytes(data, opts, ct); css=css_rewrite(css,u,fetcher,opts)
                        n.set('href', data_url(css.encode('utf-8'), 'text/css'))
            elif 'icon' in rel and n.get('href'):
                if opts.no_images: n.remove('href')
                else: embed_attr(n,'href',base,fetcher,opts,'image')
            elif n.get('href'):
                n.set('href', abs_url(n.get('href'), base))
        elif tag=='style':
            if opts.no_css: n.children=[]
            else:
                css=''.join(c.data if c.kind=='text' else serialize_node(c) for c in n.children)
                n.children=[Node('text',data=css_rewrite(css,base,fetcher,opts))]
        elif tag=='script':
            if opts.no_js:
                n.remove('src'); n.children=[]
            elif n.get('src'):
                u=abs_url(n.get('src'), base); data,ct,err=fetcher.fetch(u)
                n.remove('src')
                n.children=[Node('text',data=decode_bytes(data,opts,ct) if not err and data is not None else '')]
        elif tag=='img':
            embed_attr(n,'src',base,fetcher,opts,'image')
            if n.get('srcset') is not None: n.set('srcset', rewrite_srcset(n.get('srcset'),base,fetcher,opts,'image'))
        elif tag=='source':
            pk=attr_parent_kind(parent)
            kind='image' if pk=='picture' else ('audio' if pk=='audio' else ('video' if pk=='video' else 'image'))
            if n.get('src') is not None: embed_attr(n,'src',base,fetcher,opts,kind)
            if n.get('srcset') is not None:
                if kind=='image': n.set('srcset', rewrite_srcset(n.get('srcset'),base,fetcher,opts,'image'))
                elif (kind=='audio' and opts.no_audio) or (kind=='video' and opts.no_video): n.remove('srcset')
        elif tag=='video':
            embed_attr(n,'src',base,fetcher,opts,'video')
            if opts.no_video: n.remove('poster')
            else: embed_attr(n,'poster',base,fetcher,opts,'image')
        elif tag=='audio':
            embed_attr(n,'src',base,fetcher,opts,'audio')
        elif tag in ('iframe','frame'):
            if opts.no_frames:
                if n.get('src') is not None: n.set('src','')
            elif n.get('src'):
                u=abs_url(n.get('src'), base); data,ct,err=fetcher.fetch(u)
                if err or data is None: n.remove('src')
                else:
                    sub=parse_html(decode_bytes(data,opts,ct))
                    transform(sub,u,fetcher,opts,target_url=u,is_http_target=urllib.parse.urlparse(u).scheme in ('http','https'))
                    n.set('src', data_url(serialize_doc(sub).encode('utf-8'),'text/html'))
        elif tag=='body':
            embed_attr(n,'background',base,fetcher,opts,'image')
        elif tag=='form' and n.get('action'):
            n.set('action', abs_url(n.get('action'), base))
        elif tag in ('a','area') and n.get('href'):
            n.set('href', abs_url(n.get('href'), base))
        for c in list(n.children): walk(c,n)
    walk(doc['html'])

    # unwrap noscript by changing serializer-relevant marker nodes
    if opts.unwrap_noscript:
        def unwrap(parent):
            new=[]
            for c in parent.children:
                if c.kind=='element' and c.tag=='noscript':
                    new.append(Node('comment',data='noscript')); new.extend(c.children); new.append(Node('comment',data='/noscript'))
                else:
                    if c.kind=='element': unwrap(c)
                    new.append(c)
            parent.children=new
        unwrap(doc['html'])

    # Automatic HTTP favicon if there is no icon link.
    has_icon=False
    for n,p in iter_nodes(head):
        if n.kind=='element' and n.tag=='link' and 'icon' in ((n.get('rel') or '').lower()): has_icon=True
    if is_http_target and not has_icon and target_url and not opts.no_images:
        pr=urllib.parse.urlparse(target_url); fav=urllib.parse.urlunparse((pr.scheme,pr.netloc,'/favicon.ico','','',''))
        data,ct,err=fetcher.fetch(fav)
        if not err and data is not None:
            head.children.append(Node('element','link',attrs=[('rel','icon'),('href',data_url(data,guess_type(fav,ct,True)))],force_close=True))

    csp=csp_value(opts)
    if csp:
        head.children.insert(0, Node('element','meta',attrs=[('http-equiv','Content-Security-Policy'),('content',csp)],force_close=True))
    head.children.append(Node('element','meta',attrs=[('name','robots'),('content','none')],force_close=True))

def csp_value(opts):
    parts=[]
    if opts.isolate: parts.append("default-src 'unsafe-eval' 'unsafe-inline' data:;")
    if opts.no_css: parts.append("style-src 'none';")
    if opts.no_fonts: parts.append("font-src 'none';")
    if opts.no_frames: parts.append("frame-src 'none'; child-src 'none';")
    if opts.no_js or opts.mhtml: parts.append("script-src 'none';")
    if opts.no_images: parts.append("img-src data:;")
    return ' '.join(parts)

def metadata_comment(source_display, is_local):
    ts=time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())
    if is_local: return '<!-- Saved from local source at '+ts+' using monolith v'+VERSION+' -->\n'
    return '<!-- Saved from '+source_display+' at '+ts+' using monolith v'+VERSION+' -->\n'

def sanitize_filename(s):
    return ''.join('_' if c in '/\\:*?"<>|' else c for c in s)

def apply_output_template(path, doc):
    title=''
    for n,p in iter_nodes(doc['html']):
        if n.kind=='element' and n.tag=='title': title=text_content(n); break
    ts=time.strftime('%Y-%m-%dT%H_%M_%SZ', time.gmtime())
    return path.replace('%title%', sanitize_filename(title)).replace('%timestamp%', ts)

def mhtml_wrap(html_text):
    return 'MIME-Version: 1.0\nContent-Type: multipart/related; boundary="----=_NextPart_000_0000"\n\n------=_NextPart_000_0000\nContent-Type: text/html; charset="utf-8"\nContent-Location: http://example.com/\n\n' + html_text + '\n------=_NextPart_000_0000--\n'

def main(argv):
    opts=parse_args(argv)
    fetcher=Fetcher(opts)
    kind,url=classify_target(opts.target)
    is_local=False; source_display=url or ''
    if kind=='stdin':
        data=sys.stdin.buffer.read(); ct=None; base=opts.base_url or ''
    else:
        if not allowed_url(url, opts):
            sys.stderr.write('Error: could not retrieve target document\n'); return 1
        data,ct,err=fetcher.fetch(url, target=True)
        if err or data is None:
            sys.stderr.write('Error: could not retrieve target document\n'); return 1
        base=opts.base_url or url; is_local=urllib.parse.urlparse(url).scheme=='file'; source_display=url
    text=decode_bytes(data, opts, ct)
    doc=parse_html(text)
    transform(doc, base, fetcher, opts, target_url=(url if kind!='stdin' else opts.base_url), is_http_target=(kind in ('http','https') or (url and urllib.parse.urlparse(url).scheme in ('http','https'))))
    out=serialize_doc(doc)
    if not opts.no_metadata and kind!='stdin':
        out=metadata_comment(source_display,is_local)+out
    if opts.mhtml:
        out=mhtml_wrap(out)
    if opts.output and opts.output!='-':
        path=apply_output_template(opts.output, doc)
        with open(path,'w',encoding='utf-8') as f: f.write(out)
    else:
        sys.stdout.write(out)
    return 0

if __name__=='__main__':
    try:
        sys.exit(main(sys.argv[1:]))
    except BrokenPipeError:
        try: sys.stdout.close()
        except Exception: pass
        sys.exit(0)
